function solve(input) {
  if (typeof input !== "string" || input.length === 0) return null;
  if (!/^[IVXLCDM]+$/.test(input)) return null;
  const vals = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  const order = "IVXLCDM";
  let total = 0, i = 0, n = input.length;
  while (i < n) {
    const c = input[i];
    const next = input[i + 1];
    if (next && order.indexOf(next) > order.indexOf(c)) {
      const pair = c + next;
      if (!["IV", "IX", "XL", "XC", "CD", "CM"].includes(pair)) return null;
      total += vals[next] - vals[c];
      i += 2;
    } else {
      total += vals[c];
      i += 1;
    }
  }
  // Validate canonical form via round-trip
  if (total < 1 || total > 3999) return null;
  const map = [
    [1000, "M"], [900, "CM"], [500, "D"], [400, "CD"],
    [100, "C"], [90, "XC"], [50, "L"], [40, "XL"],
    [10, "X"], [9, "IX"], [5, "V"], [4, "IV"], [1, "I"],
  ];
  let back = "", t = total;
  for (const [v, s] of map) {
    while (t >= v) { back += s; t -= v; }
  }
  return back === input ? total : null;
}

