function solve(input) {
  let s = String(input).trim();
  let neg = false;
  if (s[0] === '+' ) s = s.slice(1);
  if (s[0] === '-') { neg = true; s = s.slice(1); }
  let dot = s.indexOf('.');
  let intPart = dot === -1 ? s : s.slice(0, dot);
  let frac = dot === -1 ? '' : s.slice(dot + 1);
  if (intPart === '') intPart = '0';
  // digits after 2 decimals
  let d1 = frac[0] || '0', d2 = frac[1] || '0';
  let rest = frac.slice(2);
  let roundUp = false;
  if (rest.length > 0) {
    let first = rest[0];
    if (first > '5') roundUp = true;
    else if (first === '5') {
      // any nonzero after?
      let anyNonZero = rest.slice(1).split('').some(c => c !== '0');
      if (anyNonZero) roundUp = true;
      else roundUp = (d2 - '0') % 2 === 1; // half: round to even
    }
  }
  // build as integer of hundredths
  let digits = intPart.replace(/^0+(?=\d)/, '') + d1 + d2;
  let n = BigInt(digits);
  if (roundUp) n += 1n;
  let str = n.toString().padStart(3, '0');
  let intOut = str.slice(0, -2) || '0';
  let fracOut = str.slice(-2);
  let out = intOut + '.' + fracOut;
  if (neg && n !== 0n) out = '-' + out;
  return out;
}

